{"version":3,"file":"technology.js","sources":["pages/technology/technology.vue","../../../HBuilderX/plugins/uniapp-cli-vite/uniPage:/cGFnZXMvdGVjaG5vbG9neS90ZWNobm9sb2d5LnZ1ZQ"],"sourcesContent":["<template>\n  <view class=\"container\">\n    <!-- 标题 -->\n    <view class=\"header\">\n      <text class=\"title\">兴趣分类</text>\n      <text class=\"subtitle\">点击分类节点展开/收起，点击叶子节点添加/删除兴趣</text>\n    </view>\n\n    <!-- 树状图可视化区域 -->\n    <view class=\"tree-visualization\">\n      <canvas canvas-id=\"treeCanvas\" class=\"tree-canvas\" @touchstart=\"handleCanvasTouch\"></canvas>\n    </view>\n\n    <!-- 操作按钮 -->\n    <view class=\"action-bar\">\n      <button class=\"refresh-btn\" @click=\"getInterest\">刷新兴趣列表</button>\n      <button class=\"reset-btn\" @click=\"resetView\">重置视图</button>\n    </view>\n  </view>\n</template>\n\n<script setup>\nimport { ref, computed, nextTick } from \"vue\"\nimport { onLoad, onReady } from '@dcloudio/uni-app'\nimport { listAll, getMyInterest, addMyInterest, deleteMyInterest } from \"../../api/api\"\n\n// 数据状态\nconst treeData = ref([])\nconst interestIds = ref(new Set())\nconst expandedKeys = ref(new Set())\n\n// 树图配置\nconst config = {\n  width: 0,\n  height: 0,\n  nodeRadius: 15,\n  levelHeight: 60,\n}\n\nconst NODE_COLORS = {\n  default: '#666666',    // 默认颜色\n  selected: '#1890ff',   // 已加入兴趣的颜色\n  hover: '#40a9ff'       // 悬停颜色（可选）\n}\t\n\n// 获取兴趣数据\nconst getInterest = async () => {\n  try {\n    const res = await getMyInterest()\n    if (res) {\n      //interestIds.value = new Set(res.map(item => item.id))\n\t  interestIds.value = new Set(res.map(item => Number(item.id)))\n      renderTree() // 重新渲染树以更新选中状态\n      uni.showToast({\n        title: '兴趣列表已更新',\n        icon: 'success'\n      })\n    } else {\n      uni.showToast({\n        title: res.msg || '获取兴趣失败',\n        icon: 'none'\n      })\n    }\n  } catch (error) {\n    console.error(\"兴趣查询失败:\", error)\n    uni.showToast({\n      title: '获取兴趣失败',\n      icon: 'none'\n    })\n  }\n}\n\n// 处理节点点击\nconst handleNodeClick = async (nodeId) => {\n  // 查找对应的节点\n  // const findNode = (nodes, id) => {\n  //   for (const node of nodes) {\n\t\t// console.log(node)\n\t\t// console.log(node.id)\n\t\t// console.log(id)\n\t\t// if (id) {\n\t\t// \tconsole.log(\"???????????\")\n\t\t// }\n  //     if (node.id === id) {\n\t\t//   console.log(\"success!!!!\")\n\t\t//   return node\n\t //  } else {\n\t\t//   console.log(\"lose!!!\")\n\t //  }\n  //     if (node.children) {\n  //       const found = findNode(node.children, id)\n  //       if (found) return found\n  //     }\n  //   }\n  //   return null\n  // }\n  \n  const findNode = (nodes, id) => {\n    for (const node of nodes) {\n      if (Number(node.id) === Number(id)) return node\n      if (node.children) {\n        const found = findNode(node.children, id)\n        if (found) return found\n      }\n    }\n    return null\n  }\n  \n  //console.log(treeData.value)\n  //console.log(nodeId)\n  const node = findNode(treeData.value, nodeId)\n  //console.log(node)\n  //console.log(\"11111\")\n  if (!node) return\n  \n  // 如果有子节点，则展开/收起\n  if (node.children?.length) {\n    toggleExpand(node)\n    renderTree()\n    return\n  }\n  \n  // 如果是叶子节点，则添加/删除兴趣\n  try {\n\t  console.log(nodeId)\n\t  console.log(interestIds)\n\t  console.log(interestIds.value)\n    if (interestIds.value.has(Number(nodeId))) {\n      const res = await deleteMyInterest(nodeId)\n\t  console.log(res)\n\t  interestIds.value.delete(nodeId)\n\t  \n\t  uni.showToast({\n\t    title: '已移除该兴趣',\n\t    icon: 'success'\n\t  })\n\t  \n      // if (res) {\n      //   interestIds.value.delete(nodeId)\n      //   uni.showToast({\n      //     title: '已移除兴趣',\n      //     icon: 'success'\n      //   })\n      // } else {\n      //   uni.showToast({\n      //     title: res || '移除失败',\n      //     icon: 'none'\n      //   })\n      // }\n    } else {\n      const res = await addMyInterest(nodeId)\n\t  console.log(res)\n\t  \n\t  interestIds.value.add(nodeId)\n\t  uni.showToast({\n\t    title: '已添加该兴趣',\n\t    icon: 'success'\n\t  })\n\t  \n      // if (res) {\n      //   interestIds.value.add(nodeId)\n      //   uni.showToast({\n      //     title: '已添加兴趣',\n      //     icon: 'success'\n      //   })\n      // } else {\n      //   uni.showToast({\n      //     title: res || '添加失败',\n      //     icon: 'none'\n      //   })\n      // }\n    }\n    renderTree() // 重新渲染以更新视觉效果\n  } catch (error) {\n    console.error(\"操作失败:\", error)\n    uni.showToast({\n      title: '操作失败',\n      icon: 'none'\n    })\n  }\n}\n\n// 查找树节点（确保在调用前定义）\nconst findNode = (nodes, id) => {\n  for (const node of nodes) {\n    if (Number(node.id) === Number(id)) return node\n    if (node.children) {\n      const found = findNode(node.children, id)\n      if (found) return found\n    }\n  }\n  return null\n}\n\n// 关闭与当前节点同层的其他节点的展开状态\nconst collapseSiblings = (node) => {\n  const parentNode = findNode(treeData.value, node.parentId)\n  if (parentNode) {\n    parentNode.children.forEach(sibling => {\n      if (sibling.id !== node.id && expandedKeys.value.has(sibling.id)) {\n        expandedKeys.value.delete(sibling.id) // 关闭其他兄弟节点的展开状态\n      }\n    })\n  }\n}\n\n// 展开/折叠节点\nconst toggleExpand = (node) => {\n\tconsole.log(\"toggleExpand !!!\")\n  // 关闭同层其他节点的展开状态\n  collapseSiblings(node)\n\n  // 切换当前节点的展开状态\n  expandedKeys.value.has(node.id)\n    ? expandedKeys.value.delete(node.id)\n    : expandedKeys.value.add(node.id)\n\n  // 重新渲染树状图\n  renderTree()\n}\n\n// 处理Canvas触摸事件\nconst handleCanvasTouch = (e) => {\n  const x = e.touches[0].x\n  const y = e.touches[0].y\n  \n  // 检测点击的是哪个节点\n  const findTouchedNode = () => {\n    for (const nodeId in nodePositions) {\n      const pos = nodePositions[nodeId]\n      const dx = pos.x - x\n      const dy = pos.y - y\n      const distance = Math.sqrt(dx * dx + dy * dy)\n      \n      if (distance <= config.nodeRadius) {\n        return parseInt(nodeId)\n      }\n    }\n    return null\n  }\n  \n  const touchedNodeId = findTouchedNode()\n  if (touchedNodeId) {\n    handleNodeClick(touchedNodeId)\n  }\n}\n\n// 构建树形结构\nconst buildTree = (data) => {\n  const map = {}\n  const roots = []\n  \n  data.forEach(item => {\n    map[item.id] = { ...item, children: [] }\n  })\n  \n  data.forEach(item => {\n    item.parentId \n      ? map[item.parentId]?.children.push(map[item.id])\n      : roots.push(map[item.id])\n  })\n  \n  return roots\n}\n\n// 初始化数据\nconst listAllInterest = async () => {\n  try {\n    const res = await listAll()\n\tconsole.log(res)\n    if (res) {\n      treeData.value = buildTree(res)\n\t  console.log(treeData)\n      if (treeData.value.length) {\n        expandedKeys.value.add(treeData.value[0].id)\n      }\n      console.log(treeData)\n      // 初始数据加载后渲染树\n      nextTick(() => {\n        renderTree()\n      })\n    } else {\n      uni.showToast({\n        title: res.msg || '获取分类失败',\n        icon: 'none'\n      })\n    }\n  } catch (error) {\n    console.error(\"获取分类失败:\", error)\n    uni.showToast({\n      title: '获取分类失败',\n      icon: 'none'\n    })\n  }\n}\n\n// 重置视图\nconst resetView = () => {\n  // 展开所有一级节点\n  expandedKeys.value.clear()\n  treeData.value.forEach(node => {\n    expandedKeys.value.add(node.id)\n  })\n  renderTree()\n}\n\n// 节点位置存储\nconst nodePositions = {}\n\n// 渲染树 - 主要函数\nconst renderTree = () => {\n\tconsole.log(\"renderTree\")\n  const ctx = uni.createCanvasContext('treeCanvas')\n  ctx.clearRect(0, 0, config.width, config.height)\n  \n  // 设置画布原点为中心\n  const originX = config.width / 2\n  const originY = 50\n  \n  // 计算可见节点\n  const visibleNodes = getVisibleNodes(treeData.value)\n  \n  // 计算节点位置\n  calculateNodePositions(visibleNodes, originX, originY)\n  \n  // 绘制连接线\n  drawTreeConnections(ctx, visibleNodes)\n  \n  // 绘制节点\n  drawTreeNodes(ctx, visibleNodes)\n  \n  ctx.draw()\n}\n\n// 获取可见节点\nconst getVisibleNodes = (nodes) => {\n  const result = []\n  \n  const traverse = (nodes, parentId = null) => {\n    nodes.forEach(node => {\n      const newNode = { ...node, parentId }\n      result.push(newNode)\n      \n      if (node.children && expandedKeys.value.has(node.id)) {\n        traverse(node.children, node.id)\n      }\n    })\n  }\n  \n  traverse(nodes)\n  return result\n}\n\n// 计算节点位置\nconst calculateNodePositions = (nodes, centerX, startY) => {\n  // 清空之前的位置\n  Object.keys(nodePositions).forEach(key => delete nodePositions[key])\n  \n  // 按层级分组节点\n  const levelNodes = {}\n  nodes.forEach(node => {\n    // 计算节点层级\n    let level = 0\n    let currentId = node.parentId\n    while (currentId !== null) {\n      level++\n      currentId = nodes.find(n => n.id === currentId)?.parentId\n    }\n    \n    if (!levelNodes[level]) levelNodes[level] = []\n    levelNodes[level].push(node)\n  })\n  \n  // 为每层分配垂直位置\n  const levels = Object.keys(levelNodes).sort((a, b) => a - b)\n  const maxNodesPerRow = 6 // 每行最多6个节点\n  let currentY = startY\n  \n  levels.forEach((level, levelIndex) => {\n    const nodesInLevel = levelNodes[level]\n    \n    // 计算该层需要多少行\n    const rowsNeeded = Math.ceil(nodesInLevel.length / maxNodesPerRow)\n    \n    // 为该层的每一行分配节点\n    for (let row = 0; row < rowsNeeded; row++) {\n      const startIndex = row * maxNodesPerRow\n      const endIndex = Math.min(startIndex + maxNodesPerRow, nodesInLevel.length)\n      const nodesInRow = nodesInLevel.slice(startIndex, endIndex)\n      \n      // 计算该行的Y坐标\n      const y = currentY + row * config.levelHeight\n      \n      // 计算水平间距\n      const totalWidth = config.width * 0.8\n      const spacing = totalWidth / (nodesInRow.length + 1)\n      \n      // 分配水平位置\n      nodesInRow.forEach((node, i) => {\n        const x = (i + 1) * spacing + (config.width - totalWidth) / 2\n        nodePositions[node.id] = { x, y }\n      })\n    }\n    \n    // 更新下一层的起始Y坐标\n    currentY += rowsNeeded * config.levelHeight\n  })\n}\n\n// 绘制连接线\nconst drawTreeConnections = (ctx, nodes) => {\n  ctx.beginPath()\n  ctx.strokeStyle = '#aaa'\n  ctx.lineWidth = 1\n  \n  nodes.forEach(node => {\n    if (node.parentId !== null) {\n      const childPos = nodePositions[node.id]\n      const parentPos = nodePositions[node.parentId]\n      \n      if (childPos && parentPos) {\n        ctx.moveTo(parentPos.x, parentPos.y + config.nodeRadius)\n        ctx.bezierCurveTo(\n          parentPos.x, parentPos.y + config.levelHeight / 2,\n          childPos.x, childPos.y - config.levelHeight / 2,\n          childPos.x, childPos.y - config.nodeRadius\n        )\n      }\n    }\n  })\n  \n  ctx.stroke()\n}\n\n// 绘制节点\nconst drawTreeNodes = (ctx, nodes) => {\n  nodes.forEach(node => {\n    const pos = nodePositions[node.id]\n    if (!pos) return\n    \n    const isSelected = interestIds.value.has(Number(node.id))\n    const hasChildren = node.children && node.children.length > 0\n    const isExpanded = expandedKeys.value.has(Number(node.id))\n    \n    // 绘制节点圆形\n    ctx.beginPath()\n    ctx.fillStyle = isSelected ? '#8bc34a' : (hasChildren ? '#6c757d' : '#2196f3')\n    ctx.arc(pos.x, pos.y, config.nodeRadius * 1.2, 0, Math.PI * 2)\n    ctx.fill()\n    \n    // 绘制边框\n    ctx.strokeStyle = '#fff'\n    ctx.lineWidth = 2\n    ctx.stroke()\n    \n    // 绘制展开/折叠图标\n    if (hasChildren) {\n      ctx.fillStyle = '#fff'\n      ctx.font = '12px sans-serif'\n      ctx.textAlign = 'center'\n      ctx.textBaseline = 'middle'\n      ctx.fillText(isExpanded ? '-' : '+', pos.x, pos.y)\n    }\n    \n    // 绘制名称\n    ctx.fillStyle = '#333'\n    ctx.font = '11px sans-serif'\n    ctx.textAlign = 'center'\n    ctx.fillText(node.name, pos.x, pos.y + config.nodeRadius + 15)\n    \n    // 绘制选中标记\n    if (!hasChildren && isSelected) {\n\t\tconsole.log(\"ffffff\")\n      ctx.fillStyle = '#fff'\n      ctx.beginPath()\n      ctx.arc(pos.x + config.nodeRadius - 5, pos.y - config.nodeRadius + 5, 4, 0, Math.PI * 2)\n      ctx.fill()\n    }\n  })\n}\n\n// 检测环境支持并设置Canvas大小\nconst setupCanvas = () => {\n  uni.getSystemInfo({\n    success: (res) => {\n      config.width = res.windowWidth\n      config.height = res.windowHeight - 120 // 减去头部和底部的高度\n    }\n  })\n}\n\nonLoad(() => {\n  listAllInterest()\n  getInterest()\n})\n\nonReady(() => {\n  setupCanvas()\n})\n</script>\n\n<style>\n.container {\n  display: flex;\n  flex-direction: column;\n  height: 100vh;\n  background-color: #f8f9fa;\n}\n\n.header {\n  padding: 20px 16px 10px;\n  background-color: #fff;\n  border-bottom: 1px solid #eee;\n}\n\n.title {\n  font-size: 18px;\n  font-weight: 600;\n  color: #333;\n  display: block;\n}\n\n.subtitle {\n  font-size: 12px;\n  color: #999;\n  margin-top: 4px;\n  display: block;\n}\n\n.tree-visualization {\n  flex: 1;\n  position: relative;\n  background-color: #fff;\n}\n\n.tree-canvas {\n  width: 100%;\n  height: 100%;\n}\n\n.action-bar {\n  padding: 15px;\n  display: flex;\n  gap: 10px;\n  background-color: #fff;\n  border-top: 1px solid #eee;\n}\n\n.refresh-btn, .reset-btn {\n  flex: 1;\n  background-color: #2196f3;\n  color: white;\n  font-size: 14px;\n  border-radius: 4px;\n}\n\n.reset-btn {\n  background-color: #6c757d;\n}\n</style>","import MiniProgramPage from 'D:/uniapp/myJoinup/joinup/pages/technology/technology.vue'\nwx.createPage(MiniProgramPage)"],"names":["ref","getMyInterest","uni","findNode","node","deleteMyInterest","addMyInterest","listAll","nextTick","nodes","onLoad","onReady","MiniProgramPage"],"mappings":";;;;;;AA2BA,UAAM,WAAWA,cAAG,IAAC,EAAE;AACvB,UAAM,cAAcA,cAAAA,IAAI,oBAAI,KAAK;AACjC,UAAM,eAAeA,cAAAA,IAAI,oBAAI,KAAK;AAGlC,UAAM,SAAS;AAAA,MACb,OAAO;AAAA,MACP,QAAQ;AAAA,MACR,YAAY;AAAA,MACZ,aAAa;AAAA,IACf;AASA,UAAM,cAAc,YAAY;AAC9B,UAAI;AACF,cAAM,MAAM,MAAMC,sBAAe;AACjC,YAAI,KAAK;AAEV,sBAAY,QAAQ,IAAI,IAAI,IAAI,IAAI,UAAQ,OAAO,KAAK,EAAE,CAAC,CAAC;AACzD,qBAAY;AACZC,wBAAAA,MAAI,UAAU;AAAA,YACZ,OAAO;AAAA,YACP,MAAM;AAAA,UACd,CAAO;AAAA,QACP,OAAW;AACLA,wBAAAA,MAAI,UAAU;AAAA,YACZ,OAAO,IAAI,OAAO;AAAA,YAClB,MAAM;AAAA,UACd,CAAO;AAAA,QACF;AAAA,MACF,SAAQ,OAAO;AACdA,sBAAAA,MAAA,MAAA,SAAA,yCAAc,WAAW,KAAK;AAC9BA,sBAAAA,MAAI,UAAU;AAAA,UACZ,OAAO;AAAA